// This file is not generated by Speakeasy — it is where 'vf auth login' sends
// the browser once it knows how sign-in went.
//
// The authorization server may host a page for that, named by
// authorization_result_uri in its metadata. It is told which of a few things
// happened and never words, names or links: the client's name and icon come
// from its registration. A server without one leaves the CLI to show its own
// page.

package oauth

import (
	"errors"
	"net/url"
)

// The outcomes the hosted page knows.
const (
	resultAuthorized = "authorized"
	resultDenied     = "denied"
	resultFailed     = "failed"
)

// The reasons it gives for resultFailed.
const (
	reasonRefused     = "refused"
	reasonUnreachable = "unreachable"
	reasonNotSaved    = "not_saved"
)

// What the person does next.
const (
	nextContinue = "continue" // go back to the command, which carries on
	nextClose    = "close"    // nothing: an agent is waiting on the command
)

// loginOutcome is how a login went, as far as the browser is told.
type loginOutcome struct {
	result string
	reason string
}

// outcomeOf is how a login that got its authorization code went.
func outcomeOf(err error) loginOutcome {
	var tokErr *tokenError
	switch {
	case err == nil:
		return loginOutcome{result: resultAuthorized}
	case errors.Is(err, ErrStoreSession):
		return loginOutcome{result: resultFailed, reason: reasonNotSaved}
	case errors.As(err, &tokErr):
		return loginOutcome{result: resultFailed, reason: reasonRefused}
	default:
		return loginOutcome{result: resultFailed, reason: reasonUnreachable}
	}
}

// resultPage is the hosted page for one login.
type resultPage struct {
	uri      *url.URL
	clientID string
	place    string
	next     string
	returnTo string
}

// newResultPage returns the hosted page for a login, or nil when the server
// has none, or not one to send a browser to.
func newResultPage(md Metadata, clientID string, getenv func(string) string, agentMode bool) *resultPage {
	uri, err := url.Parse(md.AuthorizationResultURI)
	if err != nil || uri.Host == "" {
		return nil
	}
	if uri.Scheme != "https" && (uri.Scheme != "http" || !isLoopbackHost(uri.Hostname())) {
		return nil
	}

	page := &resultPage{uri: uri, clientID: clientID, next: nextContinue, returnTo: appHere(getenv)}
	if agentMode {
		page.next = nextClose
	}
	// Over SSH the browser is on another computer than the one signed in.
	if getenv("SSH_CONNECTION") == "" {
		page.place = "this_computer"
	}
	return page
}

// address is where the page says how the login went. A nil page has none.
func (p *resultPage) address(outcome loginOutcome) string {
	if p == nil {
		return ""
	}

	returnTo := p.returnTo
	if returnTo == "" && outcome.result == resultAuthorized {
		returnTo = "voiceflow"
	}

	uri := *p.uri
	query := uri.Query()
	for _, param := range [][2]string{
		{"client_id", p.clientID},
		{"result", outcome.result},
		{"reason", outcome.reason},
		{"place", p.place},
		{"next", p.next},
		{"return_to", returnTo},
	} {
		if param[1] != "" {
			query.Set(param[0], param[1])
		}
	}
	uri.RawQuery = query.Encode()
	return uri.String()
}

// appHere names the app the command runs in, when the hosted page has a link
// that brings it back to the front.
func appHere(getenv func(string) string) string {
	switch {
	case getenv("CLAUDE_CODE_ENTRYPOINT") == "claude-desktop":
		return "claude"
	case getenv("SSH_CONNECTION") != "":
		return "" // an editor's link opens it on the browser's computer
	case getenv("CURSOR_TRACE_ID") != "":
		return "cursor"
	case getenv("__CFBundleIdentifier") == "com.microsoft.VSCode":
		return "vscode"
	default:
		return ""
	}
}
